/* ATT&CK LAB — educational Spanish drafts based on MITRE ATT&CK v20 detection records.
 * Independent commentary; never replace or mutate the original MITRE English or telemetry.
 * Every entry is a proposed educational explanation, pending human review.
 */
(()=>{'use strict';
const strategyRows=[["DET0003","Creación de cuentas de dominio en distintos sistemas","Detecta altas de identidades de dominio que no encajan con el proceso normal de aprovisionamiento. Relaciona la creación con la cuenta operadora y los primeros accesos de la identidad nueva.","Alta de una cuenta seguida de autenticación o cambios de permisos fuera del flujo aprobado.","Comprueba el evento de creación de cuenta en Windows (4720), la ejecución de herramientas de administración y, donde corresponda, los registros LDAP o de directorio.","Un alta legítima hecha por un script de TI puede producir señales similares; verifica solicitud, operador y horario.","¿Qué dato permitiría distinguir una incorporación autorizada de una cuenta creada para mantener acceso?"],["DET0008","Accesos remotos a servicios cloud con cuentas válidas","Estudia inicios de sesión cloud aparentemente válidos que se acompañan de enumeración de recursos, acceso a datos o cambios administrativos. El objetivo es identificar un uso anómalo de una identidad, no condenar un acceso aislado.","Nueva procedencia, agente de usuario o aplicación seguida de operaciones sensibles.","Compara logs de inicio de sesión del proveedor, auditoría de API, identidad, MFA y secuencia de acciones realizadas.","La geolocalización por IP, las VPN y los agentes automatizados generan falsos positivos; correlaciona identidad y actividad.","¿Qué operación posterior convertiría un inicio de sesión inesperado en un caso de investigación prioritario?"],["DET0021","Detención inesperada de servicios en varios sistemas","Busca interrupciones o desactivaciones de servicios críticos y las relaciona con la cuenta, el proceso y otras operaciones cercanas. La detención puede ser parte del mantenimiento o de una acción de impacto.","Parada de servicios de seguridad, bases de datos o máquinas virtuales seguida de cambios destructivos o fallos.","Revisa procesos y registros del gestor de servicios: Windows, systemd, launchd o registros de administración de ESXi, según plataforma.","Los parches, las copias de seguridad y las ventanas de mantenimiento también detienen servicios; una parada sola no demuestra sabotaje.","¿Qué cambios y aprobaciones comprobarías antes de escalar una parada de SQL o sshd?"],["DET0034","Enumeración de procesos con contexto sospechoso","Identifica consultas al listado de procesos, especialmente cuando las ejecuta un proceso padre o una identidad inusual. Estas consultas se usan tanto en diagnóstico como en reconocimiento.","Ejecución inesperada de tasklist, Get-Process o ps asociada a actividad posterior no habitual.","Compara creación de procesos, comandos, identidad, árbol padre-hijo y accesos a /proc cuando haya sensores que los recojan.","La enumeración rutinaria de procesos es frecuente en herramientas de supervisión y soporte.","¿Qué relación temporal haría relevante una lista de procesos obtenida tras un inicio de sesión remoto?"],["DET0054","Phishing interno desde cuentas aparentemente fiables","Relaciona envíos de mensajes internos sospechosos con posibles anomalías de la cuenta emisora y la interacción posterior de los destinatarios. El origen interno no garantiza legitimidad.","Mensajes inusuales con enlaces o adjuntos desde una identidad con acceso reciente anómalo.","Cruza auditoría de correo o colaboración, inicios de sesión, clics y ejecución de archivos cuando exista esa telemetría.","Un reenvío o envío legítimo puede parecerse a una campaña; no atribuyas compromiso sin evidencias adicionales.","¿Qué verificarías primero: autenticación del remitente, contenido del enlace o actividad en el equipo receptor?"],["DET0072","Cambios en scripts de inicio de sesión y su ejecución","Busca modificaciones en rutas, archivos o atributos de scripts de inicio de sesión y comprueba si llegaron a ejecutarse al autenticarse un usuario.","Cambio no autorizado de configuración seguido de ejecución de scripts en sesiones posteriores.","Revisa GPO, atributos de usuario, auditoría de archivos y procesos iniciados tras el logon.","El despliegue corporativo de scripts por directiva también produce estas señales.","¿Cómo demostrarías que una modificación de script no pertenecía a un cambio aprobado?"],["DET0104","Modificación de mecanismos de autenticación","Estudia alteraciones de componentes que intervienen en el inicio de sesión: paquetes de autenticación en Windows, PAM en Linux o políticas del proveedor de identidad.","Cambios de configuración o módulos de autenticación asociados a cuentas o procesos no previstos.","Revisa auditoría de archivos y registro, cargas de módulos, cambios en políticas IdP y actividad administrativa.","Un despliegue de identidad, MFA o agente de seguridad puede cambiar estos mecanismos de forma legítima.","¿Qué copia de configuración y qué registro de cambios usarías para validar una modificación de PAM?"],["DET0107","Enlaces de spearphishing y comportamiento posterior","Relaciona la recepción de un enlace dirigido con su apertura, redirecciones, autorizaciones OAuth y posibles acciones posteriores. Una URL sospechosa no equivale a compromiso.","Correo con enlace seguido de navegación atípica, concesión de permisos o ejecución inesperada.","Cruza metadatos de mensajes, proxy o navegador, registros de autenticación y auditoría de consentimiento OAuth.","El clic puede ser de un analizador de correo y la redirección puede ser legítima; verifica quién hizo qué.","¿Qué evidencias permiten distinguir un enlace abierto por el usuario de una inspección automática?"],["DET0160","Generación anómala de solicitudes de MFA","Investiga secuencias de solicitudes de MFA excesivas o inesperadas en relación con accesos de una identidad. Puede reflejar fatiga de notificaciones o problemas de configuración.","Muchas solicitudes, rechazos o caducidades seguidas de acceso desde origen inusual.","Compara registros del IdP, aplicación, origen, resultado del reto y dispositivo de autenticación.","Errores de sincronización y usuarios con varios dispositivos pueden generar repeticiones legítimas.","¿Qué evidencia adicional necesitarías antes de decir que una aprobación MFA fue fraudulenta?"],["DET0183","Transferencia lateral de herramientas entre equipos","Busca copias de archivos o herramientas entre hosts seguidas de ejecución o cambios de persistencia. Las transferencias administrativas son habituales y exigen contexto.","Transferencia a rutas inusuales y ejecución cercana desde otro sistema.","Correlaciona SMB, SCP, rsync o SFTP con archivos creados, procesos y usuarios de origen y destino.","Un despliegue de software puede reproducir la misma secuencia; coteja inventario y cambio autorizado.","¿Qué comprobarías si un script aparece por primera vez en varios servidores después de usar scp?"],["DET0234","Acceso sensible a memoria y almacenes de credenciales","Relaciona accesos a LSASS, archivos SAM u otras áreas sensibles con procesos y operaciones posteriores. Se centra en señales de posible extracción, no en afirmar robo consumado.","Lectura de memoria o claves protegidas por un proceso no esperado y creación de archivos cercanos.","Comprueba accesos a procesos, privilegios, registro y telemetría de ficheros disponible en cada sistema.","EDR, antivirus y depuradores pueden acceder legítimamente a memoria sensible; una lectura aislada no prueba exfiltración.","¿Cómo distinguirías una exploración autorizada del proceso LSASS de una acción no prevista?"],["DET0236","Adjuntos de spearphishing y ejecución posterior","Relaciona un mensaje dirigido con la descarga o apertura de su adjunto y la ejecución anómala que pudiera seguir. La entrega y la infección son hechos diferentes.","Adjunto de origen inesperado seguido de intérprete, proceso hijo o conexión de red.","Cruza metadatos de correo, creación de archivos, origen del proceso y actividad del equipo destinatario.","Las aplicaciones ofimáticas ejecutan procesos legítimos y los filtros pueden abrir archivos en sandbox.","¿Qué secuencia de eventos respaldaría la investigación de un adjunto, más allá de haberlo recibido?"],["DET0259","Uso y comunicaciones de herramientas de escritorio remoto","Estudia la ejecución de herramientas RMM, VNC y escritorio remoto y sus conexiones posteriores. Son útiles para soporte legítimo, pero también pueden habilitar acceso no aprobado.","Nueva instalación o ejecución de software remoto seguida de conexión exterior o sesión desconocida.","Revisa inventario autorizado, procesos, archivos instalados, reglas del cortafuegos y flujo de red.","Que una herramienta sea comercial o esté firmada no significa que esté autorizada, ni su uso prueba intrusión.","¿Qué pruebas pedirías al equipo de soporte antes de clasificar una nueva sesión RMM como sospechosa?"],["DET0327","Accesos RDP y actividad posterior en Windows","Investiga inicios de sesión mediante escritorio remoto y las acciones ejecutadas tras entrar. Correlacionar el acceso con procesos y recursos ayuda a priorizar casos.","Inicio de sesión RDP seguido de cmd, PowerShell, archivos sensibles o conexiones laterales no habituales.","Revisa eventos de sesión Windows (4624, 4778, 4779), procesos y conexiones de red cuando estén auditados.","Un administrador puede ejecutar las mismas herramientas tras conectarse; necesita justificación de tarea y origen.","¿Qué procesos y destinos revisarías durante los minutos posteriores a un acceso RDP inesperado?"],["DET0440","Ejecución indirecta de PowerShell mediante SyncAppvPublishingServer.vbs","Busca invocaciones de SyncAppvPublishingServer.vbs que contienen instrucciones PowerShell, combinando intérpretes firmados y actividad posterior.","Ejecución de wscript o cscript con el script y parámetros que incorporan PowerShell.","Correlaciona creación de procesos Sysmon, comandos PowerShell y módulos cargados cuando haya cobertura.","La presencia de un ejecutable firmado no autoriza la cadena, pero tampoco demuestra por sí sola malware.","¿Qué comprobarías en la línea de comandos y el proceso padre para explicar una invocación anómala?"],["DET0451","Persistencia mediante perfiles de PowerShell","Vigila cambios en archivos de perfil de PowerShell y nuevas sesiones que los cargan. Un perfil legítimo personaliza el entorno; su modificación no autorizada puede lanzar código.","Cambio inesperado de profile.ps1 seguido de PowerShell sin -NoProfile.","Comprueba auditoría de ficheros, propietario del cambio, contenido revisado de forma segura y ejecuciones posteriores.","Administradores y desarrolladores modifican perfiles con normalidad; verifica cuentas, equipos y cambios aprobados.","¿Por qué una modificación del perfil sin ejecución posterior no basta para afirmar persistencia activa?"],["DET0455","Detección de abuso de PowerShell en la ejecución de instrucciones","Relaciona invocaciones de PowerShell y automatización .NET con argumentos inusuales, procesos padres, scripts y comunicaciones posteriores.","Lanzamiento desde Office u otro padre inesperado, instrucciones codificadas o secuencias de ejecución anómalas.","Revisa creación de procesos, registros PowerShell 4103/4104 cuando estén habilitados y tráfico de red vinculado.","-EncodedCommand, tareas programadas y módulos administrativos pueden ser legítimos; analiza finalidad y autorización.","¿Qué información contextual permite diferenciar un despliegue automatizado de una ejecución maliciosa?"],["DET0463","Fallos de autenticación repetidos y posible fuerza bruta","Detecta concentraciones de autenticaciones fallidas y su relación con éxitos posteriores, origen y número de cuentas objetivo.","Ráfagas de fallos sobre una cuenta o muchas cuentas desde un origen y posterior acceso exitoso.","Correlaciona logs de inicio de sesión Windows, PAM/SSH o IdP, IP, identidad, tiempos y resultados.","Usuarios que olvidan credenciales, servicios mal configurados y proxies compartidos elevan falsos positivos.","¿Cómo diferenciarías fuerza bruta contra una cuenta de una pulverización de contraseñas contra muchas?"],["DET0460","Intentos de acceso con credenciales reutilizadas en varios servicios","Relaciona numerosos intentos de autenticación contra cuentas y servicios distintos con posibles combinaciones de usuario y contraseña previamente expuestas. La telemetría no demuestra por sí sola que la contraseña proceda de una filtración.","Muchos usuarios objetivo desde un origen o sesión, intentos en RDP, SSH o aplicaciones cloud y posibles accesos exitosos después de los fallos.","Revisa eventos de autenticación y contexto de IP, ventana temporal, cuentas, aplicaciones y resultados en Windows, Linux, IdP, SaaS y dispositivos de red.","El NAT, las pruebas autorizadas y los clientes mal configurados pueden concentrar fallos; sin una fuente de credenciales expuestas no puede verificarse que haya reutilización de claves.","¿Qué combinación de registros y verificación externa permitiría diferenciar fuerza bruta, pulverización de contraseñas y reutilización de credenciales?"]];
const analyticRows=[["AN0006","Alta de usuario de dominio en Windows","Correlaciona creación de cuentas AD con herramientas como net user o PowerShell y los primeros accesos de la nueva identidad.","Verifica 4720, proceso creador y cuenta operadora antes de relacionar el alta con una intrusión."],["AN0007","Alta de usuario de dominio desde Linux","Relaciona utilidades de administración de directorio como samba-tool o ldapmodify con modificaciones LDAP y autenticaciones posteriores.","Comprueba los registros de comandos y directorio realmente desplegados; no presupongas visibilidad de LDAP."],["AN0017","Inicio de sesión cloud y enumeración posterior","Vincula un acceso cloud desde contexto atípico con enumeración o cambios de infraestructura mediante CLI o API.","Compara ConsoleLogin, AssumeRole y acciones posteriores con la línea base del titular."],["AN0018","Acceso federado y concesiones en IdP","Analiza autenticaciones SSO y autorizaciones OAuth seguidas de enumeración o cambios de permisos.","Valida aplicaciones cliente, consentimiento y alcance antes de valorar el acceso."],["AN0019","Acceso a correo o documentos cloud","Investiga accesos M365 o Google Workspace desde orígenes o herramientas poco habituales y la lectura de recursos sensibles.","Revisa registros de acceso a documentos y buzones junto al inicio de sesión."],["AN0061","Parada de servicios de Windows","Relaciona herramientas que detienen servicios críticos con privilegios usados y cambios cercanos.","Consulta procesos y eventos de servicios, contrastándolos con despliegues y mantenimiento."],["AN0062","Parada de servicios Linux con systemd","Conecta uso de systemctl o service con interrupciones de servicios y posibles cambios de archivos.","Valida execve, mensajes de systemd y alcance temporal en el servidor afectado."],["AN0095","Consulta inusual de procesos en Windows","Analiza ejecuciones de tasklist o Get-Process asociadas a padres inesperados o accesos posteriores.","Contrasta 4688 o procesos Sysmon con el papel legítimo de la cuenta."],["AN0096","Enumeración de procesos y /proc en Linux","Cruza ps, top o lecturas de /proc con usuario, shell y contexto administrativo.","Revisa execve y accesos a /proc solo si se auditan; evita alertar por supervisión ordinaria."],["AN0147","Mensajes internos después de acceso sospechoso","Investiga correos internos desde una cuenta con actividad de autenticación reciente anómala y ejecución posterior del receptor.","Relaciona 4624/4625 y auditoría de correo sin asumir que el remitente está comprometido."],["AN0150","Phishing mediante herramientas colaborativas SaaS","Relaciona mensajes, enlaces y archivos enviados por cuentas internas con clics o usos posteriores de credenciales.","Revisa auditoría de la plataforma y evita equiparar envío con ejecución."],["AN0199","Modificación de scripts de logon en Windows","Correlaciona cambios en scripts o GPO con ejecución tras una autenticación.","Comprueba propietario del cambio, auditoría de archivos y eventos de aplicación de directivas."],["AN0287","Cambios en paquetes de autenticación Windows","Detecta modificaciones sensibles del Registro, bibliotecas de autenticación o accesos a LSASS.","Valida 4657, accesos y cargas de módulos según cobertura antes de inferir manipulación."],["AN0288","Cambios de módulos PAM en Linux","Busca escritura en /etc/pam.d/ o instalación inesperada de módulos de autenticación.","Compara integridad, autor y fecha con el sistema de gestión de configuración."],["AN0290","Cambios de políticas de autenticación del IdP","Investiga modificaciones en reglas MFA, políticas de acceso o propiedades de cuentas administradas.","Relaciona el evento de cambio con actor, autorización y sesiones posteriores."],["AN0298","Clic o navegación desde enlace dirigido en Windows","Relaciona enlaces de mensajes con navegación del usuario y ejecución posterior.","Diferencia inspección automática, clic humano y procesos derivados del navegador."],["AN0301","Consentimiento OAuth tras enlace dirigido","Investiga autorizaciones de aplicaciones a partir de enlaces recibidos por correo.","Consulta consentimiento real, permisos otorgados e identidad del aprobador."],["AN0449","Ráfagas de solicitudes MFA en IdP","Observa retos MFA repetidos sin sesión válida o desde un origen no habitual.","Compara cadencias y rechazos con dispositivos, IP y actividad normal del usuario."],["AN0452","Reintentos de MFA en Linux","Analiza autenticaciones PAM o syslog con repetición de solicitudes de segundo factor.","Revisa configuración del módulo y fallos de red como posibles alternativas."],["AN0453","Retos MFA sospechosos en aplicaciones SaaS","Correlaciona retos emitidos, denegados o expirados en aplicaciones federadas.","Comprueba si hubo aprobación válida y desde qué aplicación y origen."],["AN0516","Transferencia lateral sobre recursos Windows","Relaciona copias por SMB o Admin$ con creación de archivos y ejecución en el destino.","Contrasta 5140, Sysmon y despliegues autorizados antes de marcar transferencia maliciosa."],["AN0517","Transferencias internas mediante scp o rsync","Estudia invocaciones de scp, rsync, curl o sftp y archivos nuevos ejecutados después.","Comprueba origen, destino, ruta de escritura y tarea administrativa aprobada."],["AN0648","Acceso a LSASS o SAM desde procesos Windows","Cruza acceso a LSASS o almacenes SAM con procesos inesperados y archivos producidos.","Valida el evento de acceso a proceso y descarta agentes de seguridad autorizados."],["AN0649","Lectura de memoria de procesos sensibles Linux","Busca lecturas de /proc y uso de ptrace o herramientas de diagnóstico sobre servicios de autenticación.","Consulta permisos y propietario de la sesión; un depurador no prueba extracción."],["AN0655","Adjunto de correo y proceso anómalo en Windows","Conecta la llegada de un adjunto con archivo creado y proceso hijo inusual de Office.","Valida entrega, apertura por usuario y ejecución real antes de establecer una cadena."],["AN0656","Adjunto y ejecución de scripts en Linux","Relaciona ficheros guardados desde correo con execve o conexiones posteriores.","Comprueba cliente, usuario y ruta del archivo, sin asumir que se ejecutó."],["AN0714","Herramienta RMM y conexión remota en Windows","Detecta nuevas aplicaciones de control remoto y sus comunicaciones de red posteriores.","Coteja inventario, instalación, conexiones y autorización de soporte."],["AN0715","Servicios de escritorio remoto en Linux","Observa agentes VNC o similares y sus conexiones exteriores después del arranque.","Revisa execve, servicios y destinos permitidos; no deduzcas abuso por usar VNC."],["AN0931","Sesión RDP seguida de actividad sensible","Cruza inicios de sesión RDP con procesos, acceso a ficheros o nuevas conexiones.","Comprueba 4624, 4778/4779 y acciones en la ventana temporal configurada."],["AN1220","PowerShell mediante intérprete de VBScript","Analiza SyncAppvPublishingServer.vbs lanzado mediante wscript o cscript con instrucciones PowerShell.","Comprueba el proceso padre y el argumento real, y cruza los eventos 4103/4104 cuando existan."],["AN1245","Carga de contenido desde profile.ps1","Relaciona cambios en perfiles de PowerShell con ejecuciones que cargan el perfil.","Verifica las rutas de perfiles supervisadas y si la sesión usó -NoProfile."],["AN1252","PowerShell con argumentos o procesos padres inusuales","Combina argumentos codificados, procesos padres atípicos y actividades posteriores de PowerShell.","Revisa Sysmon 1 y PowerShell 4103/4104; valida si se trata de automatización autorizada."],["AN1275","Fallos y éxito de autenticación en Windows","Investiga ráfagas de intentos fallidos seguidas de inicio de sesión válido desde el mismo contexto.","Compara 4625/4776, 4624 y origen; ajusta umbrales para evitar ruido."],["AN1276","Intentos reiterados de SSH o PAM en Linux","Correlaciona fallos de autenticación por origen y usuario con un éxito cercano.","Comprueba auditd o auth.log/journal cuando estén disponibles y excluye mantenimientos."],["AN1277","Pulverización de contraseñas en un IdP","Busca intentos distribuidos contra muchas identidades desde un origen o patrón común.","Agrupa fallos por IP y ventana temporal; la IP compartida no identifica por sí sola al atacante."],["AN0008","Aprovisionamiento de cuentas AD desde macOS","Relaciona dsconfigad, dscl o scripts LDAP ejecutados en equipos macOS unidos a un dominio con nuevas autenticaciones de una cuenta no vista.","Contrasta estado de unión al dominio, usuario operador y actividad de directorio; una ejecución de dscl aislada no demuestra creación de una cuenta AD."],["AN0020","Uso de tokens OAuth o API en SaaS","Analiza inicios de sesión o uso de tokens en servicios SaaS seguidos de acceso a datos sensibles o cambios administrativos.","Consulta LoginSuccess, APIKeyUse y AdminAction y valida autorización de la aplicación; el uso de un token no prueba robo."],["AN0063","Parada de servicios mediante launchctl en macOS","Relaciona launchctl bootout o disable con terminación de procesos críticos y acciones posteriores desde Terminal o una sesión remota.","Revisa unifiedlog y la secuencia del proceso operador; mantenimiento y cambios de configuración pueden producir paradas legítimas."],["AN0064","Interrupción de servicios o máquinas virtuales ESXi","Vincula comandos de gestión como esxcli o vim-cmd con apagado forzado de VM y actividad posterior sobre datastores.","Consulta registros hostd, identidad y solicitud de cambio; un apagado de VM no prueba ataque destructivo."],["AN0097","Enumeración de procesos macOS fuera del uso habitual","Observa ps, top, launchctl, AppleScript o system_profiler cuando los invoca una aplicación o tarea poco frecuente.","Revisa aplicación padre, propósito del inventario y ejecuciones cercanas; el listado de procesos es normal en administración."],["AN0098","Listado de procesos ESXi desde shells no habituales","Asocia ps o esxcli system process list con accesos por SSH y cuentas de gestión que no suelen usar una shell.","Contrasta registros de shell y autenticación ESXi y el mantenimiento autorizado del hipervisor."],["AN0099","Enumeración de procesos en equipos de red","Investiga órdenes show process o equivalentes en routers y switches asociadas a roles o sesiones inesperadas.","Cruza registros CLI, syslog de administración y el inventario de operadores autorizados."],["AN0148","Mensajes internos y adjuntos desde Linux","Relaciona mensajería interna originada en Linux con actividad inesperada de la cuenta, descarga de adjuntos o ejecución posterior.","Examina registros del servidor de correo, execve y conexiones; no atribuyas compromiso por un adjunto entregado."],["AN0149","Correo interno macOS y ejecución posterior","Correlaciona actividad de Mail.app con apertura de archivos y lanzamiento poco habitual de Terminal, osascript u otros procesos.","Consulta unifiedlog y el árbol de procesos; una apertura en Preview no confirma ejecución maliciosa."],["AN0151","Reenvío de adjuntos internos mediante Office","Estudia envíos en Outlook o Word y la posterior interacción con adjuntos o macros en un entorno Office.","Verifica SendOnBehalf, MessageSend y AttachmentPreviewed donde estén disponibles; un reenvío legítimo no es evidencia de phishing."],["AN0289","Cambios de complementos de autenticación macOS","Detecta modificaciones de SecurityAgentPlugins o cargas inusuales en los componentes que participan en la autenticación.","Compara integridad de /Library/Security/SecurityAgentPlugins, identidad operadora y cambios de software aprobados."],["AN0291","Políticas IAM debilitadas en infraestructura cloud","Relaciona cambios de autenticación IAM, claves de acceso o políticas de confianza con sesiones posteriores atípicas.","Revisa auditoría CloudTrail y control de cambios; no asumas abuso únicamente por una actualización de política."],["AN0299","Correo con enlace y ejecución posterior en Linux","Correlaciona mensajes con URLs, navegación desde el usuario y procesos inesperados iniciados por un navegador Linux.","Comprueba eventos de correo, proxy y auditd execve; un clic o descarga no implica ejecución."],["AN0300","Enlace dirigido y navegador en macOS","Relaciona un enlace recibido en Mail.app con Safari o Chrome y posibles procesos osascript o Terminal derivados.","Valida URL, redirecciones y procesos padres en unifiedlog; distingue filtros automáticos de interacciones humanas."],["AN0450","Solicitudes MFA repetidas en IaaS","Agrupa retos MFA repetidos, fallos y discrepancias entre dispositivo y origen en la misma sesión cloud.","Contrasta los eventos de autenticación del proveedor con el IdP real; los fallos solos no prueban fatiga MFA."],["AN0451","Fallos de acceso Windows antes de retos MFA","Vincula múltiples eventos de autenticación fallida con solicitudes MFA cercanas sobre cuentas no habituales.","Verifica 4625 y telemetría del segundo factor en su proveedor; Windows Security no registra por sí solo el reto MFA."],["AN0454","Retos MFA repetidos en macOS corporativo","Investiga intentos de acceso en macOS que provocan múltiples desafíos mediante integración empresarial de identidad.","Consulta unifiedlog y la auditoría del IdP; comprueba errores de sincronización y enrolamiento del dispositivo."],["AN0518","Copia interna de ejecutables hacia macOS","Relaciona scp, rsync o herramientas de sincronización con archivos nuevos ejecutados poco después en el destino macOS.","Consulta creación de archivos y procesos, en especial LaunchAgents, y contrasta despliegues aprobados."],["AN0519","Transferencia lateral de archivos en ESXi","Investiga cargas a datastores o sesiones scp/ssh que crean VMX, VMDK o scripts y su ejecución posterior.","Correlaciona hostd, registros de datastore y usuarios de vSphere; migraciones y copias de VM son frecuentes."],["AN0650","Acceso a llavero o memoria sensible en macOS","Relaciona lecturas de Keychain o memoria protegida con procesos no esperados y herramientas de automatización o inspección.","Comprueba autorización, firma y auditoría de llavero; ni una consulta ni una firma ausente demuestran robo de credenciales."],["AN0657","Adjunto de Mail.app y procesos anómalos","Correlaciona recepción de adjuntos, escritura en disco y arranque poco habitual de Terminal u osascript en macOS.","Revisa procedencia del archivo, procesos padres y conexiones cercanas; recibir el adjunto no significa ejecutarlo."],["AN0716","Control remoto mediante aplicaciones macOS","Observa AnyDesk, TeamViewer o Chrome Remote Desktop y las sesiones de red asociadas a cambios locales o acceso inesperado.","Comprueba agente autorizado, firma de la aplicación, inicio de sesión y conectividad antes de declarar compromiso."],["AN1278","Ráfagas de autenticaciones fallidas macOS","Identifica intentos fallidos reiterados en loginwindow o sshd registrados en unifiedlog.","Agrupa por origen, cuenta y tiempo, compara con contraseñas caducadas y cuentas de automatización."],["AN1279","Fallos de acceso y éxito posterior en SaaS","Relaciona intentos repetidos de inicio de sesión contra aplicaciones SaaS y eventuales accesos posteriores.","Consulta los eventos de autenticación de cada aplicación e IdP; un éxito desde IP compartida no implica credenciales adivinadas."],["AN0188","Correo de phishing en Windows y ejecución posterior","Correlaciona correo con enlaces o adjuntos sospechosos con creación de ficheros, procesos iniciados y tráfico posterior en Windows.","Comprueba metadatos del mensaje, Sysmon 11 y 1 cuando estén disponibles y proceso padre; recibir correo no prueba infección."],["AN0189","Adjuntos y enlaces de correo en Linux","Busca mensajes con cabeceras anómalas seguidos de escritura de ficheros o ejecución desde directorios de correo.","Cruza registros del cliente o servidor de correo con auditd execve; valida que el archivo fue realmente ejecutado."],["AN0190","Correo sospechoso y aplicaciones macOS","Relaciona Mail.app, Safari o Preview con archivos guardados y procesos poco habituales iniciados después.","Consulta unifiedlog y origen de la sesión; un análisis automático del adjunto puede producir actividad sin intervención humana."],["AN0191","Documento Office y nuevos procesos","Vincula la apertura de un documento adjunto con macros, aplicaciones hijas y comunicaciones posteriores.","Revisa auditoría M365 y eventos de procesos Sysmon; comprueba si existe macro habilitada y ejecución real."],["AN0192","Inicio de sesión anómalo en proveedor de identidad","Relaciona posible phishing de SSO con rechazos MFA, cambios de acceso condicional y sesiones desde orígenes inesperados.","Comprueba signinlogs y aplicación solicitante, sin deducir compromiso por la ubicación de la IP."],["AN0193","Phishing en herramientas de colaboración SaaS","Observa mensajes con URLs y adjuntos en plataformas colaborativas y posteriores clics, cargas o usos de tokens.","Verifica eventos de MessagePosted y actividad de cada cuenta; los mensajes pueden ser legítimos o inspeccionados automáticamente."],["AN0350","Inserción de claves SSH en Linux","Investiga escrituras en ~/.ssh/authorized_keys y los procesos que modificaron el archivo.","Cruza auditd PATH y execve con control de cambios; una nueva clave puede proceder de aprovisionamiento legítimo."],["AN0351","Nuevas claves autorizadas SSH en macOS","Relaciona modificaciones de authorized_keys en macOS con scripts o editores y el contexto del proceso padre.","Consulta unifiedlog y autenticación SSH; confirma que la clave se utilizó y pertenece a una identidad no autorizada."],["AN0352","Cambios de claves SSH desde metadatos cloud","Analiza actualizaciones de metadatos de instancias que pueden incorporar claves públicas SSH.","Comprueba compute.instances.setMetadata, actor y estado de la VM; no todos los proveedores materializan claves de la misma manera."],["AN0353","Alteración de autenticación SSH en ESXi","Detecta escrituras en rutas de claves autorizadas ESXi o cambios de sshd_config que habilitan acceso.","Consulta auditoría de shell y configuración de acceso; evalúa si es un cambio autorizado de emergencia."],["AN0354","Claves SSH añadidas en equipos de red","Investiga comandos de configuración como ip ssh pubkey-chain y su asociación con cuentas de administración.","Valida registros CLI, identidad del operador y configuración anterior del dispositivo."],["AN0590","Accesos de cuentas de dominio a varios equipos Windows","Correlaciona autenticaciones de cuentas válidas en hosts y horarios no habituales con sesiones y procesos posteriores.","Compara 4624/4625/4768/4769 y origen real, teniendo en cuenta accesos por VPN o servidores de salto."],["AN0591","Cuentas de dominio usadas en Linux mediante sssd","Busca accesos a sistemas Linux integrados con AD mediante sssd o winbind que no encajan con el horario o equipo habitual.","Relaciona PAM, sshd, sssd y sudo con tickets o sesiones válidas; comprueba tareas autorizadas."],["AN0592","Acceso de identidades AD a equipos macOS","Observa inicios de sesión de cuentas de red o móviles fuera de patrones conocidos en equipos macOS unidos al dominio.","Consulta logs de Open Directory y auditoría de identidad; los cambios de red alteran la procedencia aparente."],["AN0593","Acceso a vSphere con cuentas de dominio","Investiga autenticaciones de usuarios de dominio en ESXi o vCenter con roles o interfaces inesperadas.","Correlaciona vpxd, hostd y pertenencia a grupos autorizados; una sesión válida no demuestra abuso."],["AN1262","Múltiples intentos de acceso a RDP o SMB en Windows","Analiza errores de autenticación desde un origen sobre varios usuarios de Windows en una ventana breve.","Revisa Security 4625, cuenta y origen, sin afirmar que las contraseñas procedan de filtraciones sin evidencia adicional."],["AN1263","Intentos repetidos contra SSH o PAM en Linux","Relaciona fallos de inicio de sesión de distintas cuentas desde una IP con servicios SSH o PAM.","Consulta syslog o journal de sshd, identidad y tiempo; un host de pruebas puede generar tráfico parecido."],["AN1264","Errores de acceso con cuentas alternantes en macOS","Agrupa fallos de loginwindow o servicios remotos con múltiples nombres de usuario.","Revisa unifiedlog y origen del acceso; distingue problemas de directorio de un patrón de credenciales reutilizadas."],["AN1265","Posibles credenciales reutilizadas en el IdP","Observa intentos de autenticación de distintas identidades desde el mismo origen hacia Azure AD u otros IdP.","Consulta signinlogs, resultado y cliente; la procedencia de contraseñas filtradas requiere comprobación independiente."],["AN1266","Fallos de autenticación entre aplicaciones SaaS","Investiga muchos accesos fallidos en aplicaciones cloud que afectan a varias cuentas.","Revisa registros de aplicaciones e IdP y distingue intentos automatizados de problemas de SSO."],["AN1267","Intentos de acceso a routers y cortafuegos","Analiza fallos de autenticación AAA, RADIUS o TACACS sobre identidades variadas desde un origen.","Valida syslog y la central de identidades, y excluye comprobaciones autorizadas de disponibilidad."],["AN1268","Autenticaciones anómalas en APIs de contenedores","Busca fallos repetidos contra API de Kubernetes o servicios de autenticación de contenedores.","Consulta auditoría real del clúster e identidad de servicio; no todos los accesos usan pares usuario-contraseña."],["AN1269","Intentos de acceso a buzones cloud","Relaciona múltiples fallos contra OWA, Exchange o M365 desde una misma IP y sobre distintos buzones.","Revisa auditoría de autenticación M365 y eventos de inicio de sesión; los proxies de empresa agregan orígenes."],["AN1270","Fallos de inicio de sesión en infraestructura cloud","Investiga muchos intentos fallidos hacia cuentas o instancias cloud desde un origen o patrón común.","Correlaciona ConsoleLogin de CloudTrail con sesiones y políticas aplicadas; no afirmes uso de credenciales filtradas sin contraste."]];
strategyRows.push(...[["DET0001","Acceso sospechoso a metadatos de instancias cloud","Investiga consultas a servicios de metadatos de instancias IaaS, especialmente desde contenedores o procesos que no deberían solicitar credenciales temporales.","Conexiones hacia direcciones de metadatos como 169.254.169.254 desde cargas no previstas o tras indicios de SSRF.","Cruza flujos de red de la instancia, procesos originadores, auditoría cloud y controles de acceso al servicio de metadatos.","Los agentes del proveedor y las aplicaciones con roles de instancia consultan legítimamente estos servicios; la conexión aislada no prueba extracción.","¿Qué proceso realizó la petición y qué permisos tenía la identidad de la instancia?"],["DET0002","Uso anómalo de protocolos de publicación y suscripción para C2","Busca clientes o procesos inesperados que emplean MQTT, AMQP u otros protocolos de mensajería para comunicarse con brokers ajenos a los flujos corporativos.","Publicaciones periódicas o conexiones persistentes a brokers no inventariados desde intérpretes o programas de uso no habitual.","Relaciona conexiones por proceso, DNS, puertos, identidad del broker y, si existen, registros de temas y mensajes.","MQTT y AMQP también transportan telemetría industrial y aplicaciones legítimas; verifica el inventario de brokers.","¿Cómo distinguirías el tráfico de un dispositivo IoT autorizado de un canal de control ajeno?"],["DET0004","Secuestro de comandos mediante la variable PATH","Correlaciona modificaciones en la ruta de búsqueda de ejecutables con la ejecución posterior de binarios desde directorios manipulables.","Cambios en PATH o perfiles de shell seguidos de la ejecución de un nombre conocido desde una ruta inesperada.","Revisa cambios de entorno, perfiles, rutas con permisos de escritura, creación de archivos y árbol de procesos.","Herramientas de desarrollo y entornos virtuales modifican PATH habitualmente; no basta con observar el cambio.","¿Qué ruta resolvió realmente el sistema cuando se ejecutó el comando?"],["DET0005","Ejecución de utilidades renombradas con metadatos discordantes","Busca binarios cuyo nombre en disco difiere de su identidad interna y que se ejecutan desde ubicaciones o sesiones poco habituales.","Una herramienta de sistema renombrada aparece en una ruta escribible por usuarios y realiza operaciones administrativas.","Compara nombre externo, OriginalFilename, firma, hash, proceso padre y directorio de ejecución.","El empaquetado de software o las copias administrativas también pueden cambiar nombres; la discordancia exige contexto.","¿Qué evidencia demostraría que el ejecutable renombrado es una utilidad legítima y no una imitación?"],["DET0007","Enumeración inusual de relaciones de confianza del dominio","Relaciona consultas de confianza entre dominios mediante nltest, API o scripts con una sesión o una cuenta cuya función no requiere ese inventario.","Enumeración LDAP o comandos de descubrimiento de dominios desde estaciones no administrativas seguida de reconocimiento adicional.","Consulta procesos, comandos, autenticaciones y registros de directorio disponibles; documenta la cuenta y el equipo origen.","Las migraciones y auditorías de Active Directory suelen enumerar relaciones de confianza.","¿Qué actividad posterior haría más relevante una enumeración de relaciones de confianza?"],["DET0009","Manipulación de dependencias y herramientas de desarrollo","Investiga cadenas de instalación o compilación en las que una dependencia nueva modifica ejecutables o scripts y después genera ejecución o conexiones de red.","Restauración de paquetes seguida de cambios inesperados en binarios o scripts y una primera ejecución con salida a Internet.","Cruza logs de CI, manifiestos y lockfiles, hashes, firma de paquetes, procesos del gestor y destinos de red.","Los instaladores y scripts postinstall son habituales; una descarga durante la compilación no demuestra compromiso.","¿Qué cambio en un lockfile o artefacto permitiría reconstruir el origen de la dependencia?"],["DET0010","Ejecución activada por eventos fuera de la configuración esperada","Busca nuevos activadores automáticos, como suscripciones WMI o reglas equivalentes, que desencadenan procesos no aprobados.","Alta de un activador persistente seguida de ejecución automática bajo una cuenta privilegiada o fuera de horario.","Relaciona auditoría de filtros y consumidores WMI, tareas, claves de arranque y procesos resultantes según plataforma.","Las herramientas de administración y gestión instalan activadores legítimos; valida el propietario y la finalidad.","¿Qué vínculo entre el activador registrado y el proceso iniciado confirmaría la cadena observada?"],["DET0011","Tráfico de mando y control con datos de relleno","Analiza comunicaciones que incorporan contenido redundante o inusual para dificultar el reconocimiento de órdenes y respuestas.","Volúmenes o patrones de carga útil discordantes con el protocolo esperado, especialmente desde procesos poco habituales.","Cruza flujos, proporción de bytes enviados y recibidos, procesos, destino y capturas autorizadas cuando existan.","Las transferencias, compresión y protocolos propietarios también producen tramas poco habituales.","¿Qué evidencia de la carga útil apoyaría la hipótesis de datos de relleno?"],["DET0012","Diferencias entre código fuente VBA y código ejecutable","Busca documentos Office cuya representación de macros no corresponde con el código VBA visible, fenómeno asociado a VBA Stomping.","Diferencias entre flujos de origen y código compilado, con ejecución de macros desde documentos inesperados.","Analiza el documento de forma estática en un entorno seguro y correlaciona la apertura con procesos de Office y archivos creados.","Las versiones de Office y el tratamiento de macros pueden generar diferencias no maliciosas; revisa la compatibilidad.","¿Cómo comprobarías la discrepancia sin ejecutar directamente un documento no confiable?"],["DET0013","Acceso no habitual a datos locales del navegador","Investiga procesos distintos del navegador que enumeran o leen archivos de historial, marcadores o configuración del perfil.","Un script o herramienta administrativa accede a varias bases de datos de navegador fuera de un procedimiento documentado.","Relaciona accesos a archivos, usuario, proceso solicitante y acciones posteriores de copia o exportación.","La copia de perfiles, asistencia técnica y migraciones pueden leer esos archivos legítimamente.","¿Qué proceso abrió los archivos y qué datos se copiaron efectivamente?"],["DET0014","Acopio de archivos previo a una posible exfiltración","Busca agrupación de información en carpetas temporales o comprimidos antes de transferencias que no encajan con el trabajo normal.","Copias masivas de archivos sensibles hacia una ubicación de preparación y creación de archivos comprimidos.","Correlaciona auditoría de archivos, herramientas de archivado, cuenta, destino de red y solicitudes de exportación.","Los respaldos y movimientos de proyectos producen señales similares; el acopio no demuestra por sí solo exfiltración.","¿Qué conexión de red o acceso posterior corroboraría que los archivos preparados salieron del entorno?"],["DET0016","Descubrimiento del software de seguridad instalado","Investiga enumeraciones de antivirus, EDR, cortafuegos y servicios de seguridad desde cuentas o procesos que no suelen hacer inventario.","Consultas WMI, Registro o servicios seguidas de intentos de detener controles o modificar políticas.","Cruza comandos, proceso padre, identidad, inventario de agentes y cambios efectivos de configuración.","Las auditorías de activos y herramientas de soporte enumeran controles de seguridad rutinariamente.","¿Qué cambio posterior en un agente haría prioritario investigar la consulta?"],["DET0017","Instalación de compatibilidad de aplicaciones mediante sdbinst","Relaciona la creación de bases de datos de compatibilidad Windows con el uso de sdbinst.exe y cargas de módulos inesperadas.","Instalación de un shim personalizado seguida de carga de DLL o ejecución de una aplicación afectada.","Revisa comandos sdbinst, claves AppCompat, archivos .sdb, autor y módulos cargados por el proceso objetivo.","La compatibilidad de aplicaciones antiguas puede requerir shims autorizados.","¿Quién instaló la base .sdb y qué aplicación cambió su comportamiento después?"],["DET0018","Carga sospechosa de bibliotecas compartidas","Busca procesos que cargan DLL, .so o dylib desde directorios no habituales, especialmente si se escribieron poco antes de la carga.","Una biblioteca aparece en carpeta temporal o recurso remoto y enseguida es utilizada por un proceso con privilegios.","Correlaciona creación de archivos, firmas, mapeos o carga de módulos, árbol de procesos y directorios escribibles.","Las aplicaciones extensibles, instaladores y depuradores cargan bibliotecas fuera de rutas estándar.","¿Qué evidencia vincula la biblioteca recién creada con el proceso que la cargó?"],["DET0019","Carga de ejecutables sin símbolos ni cadenas reconocibles","Busca archivos ejecutables o scripts con contenido de análisis limitado cuya creación y ejecución forman una secuencia atípica.","Binario nuevo sin símbolos legibles desde una ruta temporal seguido de procesos o comunicaciones inesperadas.","Comprueba metadatos de compilación, secciones, procedencia, proceso que creó el archivo y comportamiento.","Las compilaciones optimizadas eliminan símbolos de forma habitual; la ausencia de símbolos no acredita malware.","¿Qué acción observada permite pasar de anomalía de formato a investigación de comportamiento?"],["DET0020","Cambios de inicio de shell con ejecución posterior","Investiga alteraciones de perfiles de Bash, Zsh y shells similares que introducen comandos ejecutados al abrir nuevas sesiones.","Modificación de .bashrc, .profile o .zshrc seguida de procesos o conexiones inesperadas al iniciar sesión.","Correlaciona cambios de archivo, autor, sesiones shell y procesos activados tras el siguiente inicio.","La personalización de entornos de desarrollo y administración modifica habitualmente estos perfiles.","¿Qué línea nueva del perfil originó el proceso que no estaba previsto?"],["DET0022","Autenticación NTLM forzada por archivos señuelo","Busca documentos o accesos directos con referencias remotas que inducen al equipo a intentar autenticarse por SMB o WebDAV.","Apertura o previsualización de un archivo seguida de conexión y negociación NTLM hacia un servidor externo no autorizado.","Relaciona creación y apertura del señuelo, SMB saliente, destino y auditoría de autenticación de Windows.","La vista previa y enlaces UNC corporativos también provocan conexiones; no afirmes robo de credenciales sin evidencia.","¿Qué ruta remota contenía el señuelo y a qué equipo se intentó autenticar Windows?"],["DET0023","Desempaquetado de binarios con cambios de memoria ejecutable","Busca procesos cuyo código pasa de una representación empaquetada a regiones ejecutables en memoria antes de efectuar nuevas acciones.","Asignación de memoria, escritura y ejecución desde regiones no asociadas a módulos conocidos tras lanzar un binario poco habitual.","Correlaciona carga de procesos, permisos de memoria, módulos y operaciones entre procesos, si el EDR proporciona esos datos.","Los intérpretes y compiladores JIT generan memoria ejecutable legítimamente.","¿Qué diferencia existe entre el uso normal de JIT y la secuencia observada en el proceso?"],["DET0024","Acceso inusual a cachés de tickets Kerberos","Busca lectura, copia o traslado de archivos ccache o cachés de credenciales Kerberos por programas o identidades no esperadas.","Herramientas desconocidas acceden a cachés de sesiones Kerberos y posteriormente surgen autenticaciones desde otro contexto.","Relaciona accesos de archivo o API de caché, variable KRB5CCNAME, usuario y autenticaciones posteriores.","Los clientes Kerberos y mecanismos de inicio de sesión consultan cachés legítimamente.","¿Qué nueva sesión o copia observable permitiría sospechar reutilización de tickets?"],["DET0025","Uso anómalo de aplicaciones Electron para ejecutar código","Estudia aplicaciones Electron de confianza que inician intérpretes o cargan recursos alterados fuera de un flujo de actualización normal.","Cambios en archivos .asar o configuraciones seguidos de procesos hijos como shell o scripts bajo una aplicación de escritorio.","Cruza integridad de recursos, argumentos de proceso, binario anfitrión, actualizaciones y conexiones.","Las extensiones y funciones legítimas de Electron pueden ejecutar procesos auxiliares.","¿Qué archivo de la aplicación cambió antes de que apareciera el proceso hijo?"],["DET0026","Persistencia mediante procesadores de impresión Windows","Correlaciona altas o cambios de procesadores de impresión con la escritura de DLL y su carga por el servicio de cola.","Nueva clave de procesador de impresión y DLL desconocida cargada por spoolsv.exe tras un cambio de configuración.","Revisa Registro de impresoras, archivos de bibliotecas, firmas y eventos de reinicio del spooler.","La instalación de controladores y software de impresión añade procesadores legítimos.","¿Qué instalador autorizado, si existe, registró la DLL investigada?"],["DET0027","Comunicación C2 sobre protocolos web","Busca procesos que realizan conexiones HTTP, HTTPS o WebSocket con periodicidad o destinos incompatibles con su función normal.","Programa administrativo sin función web mantiene solicitudes periódicas o envíos a un dominio inusual.","Relaciona registros de proxy, DNS, flujos, proceso originador, métodos HTTP y volumen de datos.","Las API corporativas, actualizadores y agentes de monitorización usan comunicaciones repetitivas.","¿Qué combinación de proceso, destino y secuencia temporal justifica priorizar esta conexión?"],["DET0030","Cambios no autorizados en políticas de acceso condicional","Busca modificaciones de reglas de autenticación cloud que amplían exclusiones o eliminan requisitos de MFA sin autorización.","Cambios de políticas IAM o IdP seguidos de accesos con condiciones menos restrictivas.","Consulta auditoría del proveedor, versiones de política, operador, cuentas afectadas y solicitudes de cambio.","Los ajustes de acceso condicional también responden a incidencias y despliegues aprobados.","¿Qué usuarios o aplicaciones ganaron acceso como resultado de la nueva política?"],["DET0031","Ejecución de binarios con firma no válida","Investiga ejecuciones donde los metadatos de firma no superan la verificación criptográfica y hay un contexto de proceso o ruta sospechoso.","Una aplicación aparenta estar firmada, pero su firma falla y se inicia desde una ubicación inesperada.","Verifica firma, cadena, certificado, hash, ruta y proceso padre mediante herramientas confiables.","La caducidad de certificados y empaquetados defectuosos también causan errores de validación.","¿Qué resultado concreto de la validación impide confiar en la firma declarada?"],["DET0032","Creación y uso sospechosos de archivos ocultos","Relaciona atributos de ocultación de archivos o directorios con procesos y rutas que no se ajustan al funcionamiento esperado.","Nuevos ficheros ocultos en ubicaciones sensibles creados por una cuenta o script ajeno al inventario.","Revisa eventos de creación, nombres, atributos, contenido y permisos del directorio afectado.","Las configuraciones Unix y numerosos componentes de Windows utilizan archivos ocultos legítimos.","¿Qué comportamiento posterior hizo que un archivo oculto mereciera investigación?"],["DET0033","Alteración de componentes de accesibilidad Windows","Busca sustitución de utilidades de accesibilidad o cambios del Registro que permiten iniciar otro programa desde contextos de inicio de sesión.","Cambios sobre utilman.exe o sethc.exe, o valores de depuración asociados, seguidos de ejecuciones no esperadas.","Compara hashes y firmas de binarios, claves IFEO, cuenta que realizó el cambio y procesos iniciados.","Las reparaciones del sistema y herramientas de accesibilidad aprobadas pueden modificar configuraciones.","¿Qué archivo o clave fue alterado y cómo se relaciona con una ejecución posterior?"],["DET0035","Uso bidireccional de servicios web como canal de control","Busca procesos que envían y reciben datos mediante servicios web legítimos con patrones que no se explican por su función habitual.","Solicitudes automatizadas frecuentes hacia una API pública, con respuestas o subidas correlacionadas con actividad local.","Cruza conexiones HTTPS, eventos de proceso, identidad de la API, temporización y volumen de envíos.","Muchas integraciones SaaS legítimas usan peticiones bidireccionales periódicas.","¿Qué operación local se produce después de recibir datos desde el servicio web?"],["DET0036","Registro anómalo de dispositivos en plataformas de identidad","Investiga altas de nuevos dispositivos o cambios de propietario vinculados a cuentas existentes para distinguir enrolamientos legítimos de persistencia.","Un dispositivo nuevo aparece registrado tras un inicio de sesión inusual y consigue acceso a recursos protegidos.","Comprueba auditoría de Entra ID u otro IdP, identidad que enroló el dispositivo, MFA y cumplimiento del equipo.","La renovación de portátiles y móviles produce altas frecuentes; no consideres maliciosa una inscripción aislada.","¿Qué aprobación o propiedad del dispositivo permite validar su alta?"],["DET0037","Lectura anómala de almacenes de contraseñas del navegador","Busca procesos que abren bases de datos o ficheros con credenciales de navegadores sin una función legítima de usuario o sistema.","Lecturas de Login Data o logins.json realizadas por un script desconocido y seguidas de copias o conexiones.","Correlaciona auditoría de archivos, proceso solicitante, permisos y destinos de datos, sin extraer contraseñas en la investigación.","Los gestores de contraseñas y las migraciones de perfil pueden acceder de forma autorizada.","¿Qué cuenta y programa leyeron el almacén, y para qué fin documentado?"],["DET0038","Sustitución de archivos ejecutables usados por instaladores","Busca escritura en rutas que contienen ejecutables invocados por instaladores y su ejecución posterior bajo permisos elevados.","Cambio de binario en carpeta de instalación escribible seguido de ejecución por un instalador privilegiado.","Correlaciona ACL, creación o reemplazo del ejecutable, integridad y registro de la instalación.","Las actualizaciones reemplazan ejecutables por diseño; es imprescindible verificar su origen.","¿Quién tenía permiso para escribir el binario que el instalador ejecutó?"],["DET0039","Resolución dinámica sospechosa de destinos de red","Correlaciona DNS inusual, dominios variables y conexiones posteriores desde procesos que normalmente no realizan esa actividad.","Consultas repetidas a nombres poco habituales o con alta variación seguidas de conexiones a destinos cambiantes.","Relaciona eventos DNS, respuestas, proceso originador, destinos y periodicidad, respetando la línea base del servicio.","Los CDN, balanceadores y software de seguridad pueden generar dominios dinámicos legítimos.","¿Qué proceso utiliza la resolución y con qué frecuencia se conectó a las respuestas?"],["DET0040","Retirada de mecanismos de persistencia tras su utilización","Busca eliminación de servicios, tareas, claves o unidades de arranque que habían permitido ejecuciones previas, especialmente cerca de otras anomalías.","Creación y uso de un servicio o tarea seguidos de su borrado con comandos no aprobados.","Compara la cronología de altas, ejecuciones y eliminaciones en gestores de servicios, tareas y auditoría del sistema.","Desinstalaciones, restauraciones y limpieza de mantenimiento eliminan persistencias legítimas.","¿Qué ejecución anterior vinculaba el artefacto eliminado con una actividad sospechosa?"]]);
const strategies=Object.fromEntries(strategyRows.map(([id,title,summary,signals,telemetry,limitations,question])=>[id,Object.freeze({id,title,summary,signals,telemetry,limitations,question,status:'draft_needs_review'})]));
const analytics=Object.fromEntries(analyticRows.map(([id,title,summary,verify])=>[id,Object.freeze({id,title,summary,verify,status:'draft_needs_review'})]));
const asText=entry=>entry?Object.values(entry).filter(v=>typeof v==='string').join(' '):'';
window.AttackDetectionSpanishV20=Object.freeze({
 strategy:id=>strategies[id]||null,
 analytic:id=>analytics[id]||null,
 title:(id,type)=>type==='detections'?strategies[id]?.title||'':type==='analytics'?analytics[id]?.title||'':'',
 summary:(id,type)=>type==='detections'?strategies[id]?.summary||'':type==='analytics'?analytics[id]?.summary||'':'',
 searchText:(id,type)=>asText(type==='detections'?strategies[id]:type==='analytics'?analytics[id]:null),
 coverage:Object.freeze({detections:strategyRows.length,analytics:analyticRows.length})
});
})();
